  insert(city, driverId, earnings, ts) {
    let scope = this.cities.get(city);
    if (!scope) {
      scope = { drivers: new Map(), heap: new MaxHeap() };
      this.cities.set(city, scope);
    }
    // Dedup: remove old driver entry if exists
    const old = scope.drivers.get(driverId);
    if (old) scope.sum -= old.earnings;
    // Insert new event
    scope.drivers.set(driverId, { earnings, ts });
    scope.sum = (scope.sum || 0) + earnings;
    // Update heaps...
  }

